def validate(graph):
  V = len(graph)
  for node in range(V):
    seen = set()
    for nbr in graph[node]:
      if nbr < 0 or nbr >= V:
        return False  # Invalid node index.
      if nbr == node:
        return False  # Self-loop.
      if nbr in seen:
        return False  # Parallel edge.
      seen.add(nbr)

  edges = set()
  for node1 in range(V):
    for node2 in graph[node1]:
      edge = (min(node1, node2), max(node1, node2))
      if edge in edges:
        edges.remove(edge)
      else:
        edges.add(edge)
  return len(edges) == 0

